{
  "propositions": [
    {
      "id": "P1",
      "proposition": "Section 49-1-1002(a) is amended to insert child trafficking prevention and awareness education between healthy school environment and school counseling.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "environment, child trafficking prevention and awareness education, school counseling\"."
    },
    {
      "id": "P2",
      "proposition": "Section 49-6-1304(a)(13)(B) is deleted.",
      "importance": "core",
      "section": "SECTION 2",
      "source_quote": "subdivision (a)(13)(B)"
    },
    {
      "id": "P3",
      "proposition": "The second sentence of § 49-6-1304(d) is deleted.",
      "importance": "core",
      "section": "SECTION 2",
      "source_quote": "deleting the second sentence in subsection (d)."
    },
    {
      "id": "P4",
      "proposition": "For the new section added to Title 49, Chapter 6, Part 10, child trafficking means a human trafficking offense as defined in § 39-13-314 in which the victim is under eighteen years of age.",
      "importance": "supporting",
      "section": "SECTION 3(a)",
      "source_quote": "as defined in § 39-13-314, in which the victim is less than eighteen (18) years of age."
    },
    {
      "id": "P5",
      "proposition": "All public schools must include child trafficking prevention and awareness education as a component of health education for students in every grade from kindergarten through grade twelve.",
      "importance": "core",
      "section": "SECTION 3(b)",
      "source_quote": "(b) The course of instruction in all public schools must include child trafficking"
    },
    {
      "id": "P6",
      "proposition": "Using the state board of education's adopted health education standards, LEAs and public charter schools must ensure that the required instruction is age- and grade-appropriate and advances each year through developmentally appropriate instruction and skill building.",
      "importance": "supporting",
      "section": "SECTION 3(c)",
      "source_quote": "age- and grade-appropriate and advances each year"
    },
    {
      "id": "P7",
      "proposition": "LEAs and public charter schools may use a qualified healthcare professional or social worker to assist in teaching child trafficking prevention and awareness, provided that the professional or social worker meets the requirements for assisting in teaching family life under § 49-6-1303.",
      "importance": "supporting",
      "section": "SECTION 3(d)",
      "source_quote": "meets the requirements for assisting in teaching family life under § 49-6-1303."
    },
    {
      "id": "P8",
      "proposition": "By August 1, 2026, and each August 1 thereafter, each local board of education and public charter school governing body must submit an implementation plan to the commissioner of education and publish it on the LEA or public charter school website. The plan must identify instruction delivery methods for each grade served, the professional qualifications of the person delivering instruction, and the materials and resources used.",
      "importance": "core",
      "section": "SECTION 3(e)",
      "source_quote": "(e) By August 1, 2026, and each August 1 thereafter, each local board of"
    },
    {
      "id": "P9",
      "proposition": "By July 1, 2027, and each July 1 thereafter, each local board of education and public charter school governing body must submit an implementation report to the commissioner of education. The report must verify that the required instruction was provided during the immediately preceding school year and include the grade-level delivery methods, instructor professional qualifications, and materials and resources information required for the implementation plan.",
      "importance": "core",
      "section": "SECTION 3(f)",
      "source_quote": "(f) By July 1, 2027, and each July 1 thereafter, each local board of education"
    },
    {
      "id": "P10",
      "proposition": "The act takes effect upon becoming law and applies to the 2026-2027 school year and subsequent school years.",
      "importance": "supporting",
      "section": "SECTION 4",
      "source_quote": "and applies to the 2026-2027 school year and subsequent school years."
    }
  ]
}
